describe('CRUD', () => {
  it('create → 201 with the row (defaults filled, audit columns set); get returns it', async () => {
    const tag = unique()
    const res = await create(body(tag)).expect(201)
    const row = res.body.data
    expect(row).toMatchObject({
      id: expect.any(Number),
      ...body(tag),
      sortNo: 0,
      enabled: true,
      note: null,
      createdBy: expect.any(Number),
    })
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt)
    const got = await call('admin', 'get', `/${row.id}`).expect(200)
    expect(got.body.data).toEqual(row)
  })

  it('list: newest first by the sort whitelist, all live rows counted, paging, enabled equals', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const res = await list({ sort: '-id', pageSize: 3 })
    expect(idsOf(res)).toEqual([...ids].reverse())
    expect(res.body.data.total).toBe(await count())
    expect(idsOf(await list({ sort: '-id', page: 2, pageSize: 2 }))[0]).toBe(ids[0])
    const off = (await add(body(unique(), { enabled: false }))).id
    expect(idsOf(await list({ enabled: 'false', sort: '-id', pageSize: 1 }))).toEqual([off])
    expect(idsOf(await list({ enabled: 'true', sort: '-id', pageSize: 1 }))).toEqual([ids[2]])
  })

  it('list: text filters contain (LIKE wildcards literal) and combine with enabled', async () => {
    const tag = unique()
    for (const suffix of ['a', 'b', 'c']) await add(body(`${tag}-${suffix}`))
    await add(body(`${tag}-off`, { enabled: false }))
    await add(body(`${tag}_x`))

    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const keys = (res: request.Response) => res.body.data.items.map((r: { name: string }) => r.name)
    const res = await list({ name: `${tag}-`, enabled: 'true', sort: '-id' })
    expect(keys(res)).toEqual([`${tag}-c`, `${tag}-b`, `${tag}-a`])
    expect(res.body.data.total).toBe(3)
    expect(keys(await list({ name: tag, enabled: 'false' }))).toEqual([`${tag}-off`])
    // `%` and `_` in the filter are plain characters
    expect(keys(await list({ name: `${tag}_` }))).toEqual([`${tag}_x`])
    expect(keys(await list({ code: `${tag}-b code` }))).toEqual([`${tag}-b`])
    const page2 = await list({ name: `${tag}-`, sort: 'id', page: 2, pageSize: 2 })
    expect(keys(page2)).toEqual([`${tag}-c`, `${tag}-off`])
    expect(page2.body.data.total).toBe(4)
  })

  it('update changes the fields sent and keeps the others; enabled toggles', async () => {
    const tag = unique()
    const { id } = await add(body(tag))
    await call('admin', 'put', `/${id}`, { code: `${tag} renamed` }).expect(200)
    await call('admin', 'put', `/${id}/enabled`, { enabled: false }).expect(200)
    expect((await call('admin', 'get', `/${id}`)).body.data).toMatchObject({
      ...body(tag),
      code: `${tag} renamed`,
      enabled: false,
    })
  })

  it('a row PUT back as loaded (nulls included, as the edit form sends it) → 200, unchanged', async () => {
    const row = await add(body(unique()))
    const loaded = Object.fromEntries(FORM.map((f) => [f, row[f]]))
    await call('admin', 'put', `/${row.id}`, loaded).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data).toMatchObject(loaded)
  })

  it('delete and batch delete (soft: the rows stay, marked deleted)', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    await call('admin', 'delete', `/${ids[0]}`).expect(200)
    await call('admin', 'post', '/batch-delete', { ids: ids.slice(1) }).expect(200)
    expect(
      await ds.query('SELECT id FROM iam_role WHERE id IN (?) AND deleted_at IS NULL', [ids]),
    ).toEqual([])
    expect(await ds.query('SELECT id FROM iam_role WHERE id IN (?)', [ids])).toHaveLength(3)
    await call('admin', 'get', `/${ids[0]}`).expect(404)
    // unique among live rows only: a deleted row's name can be used again
    const { name } = (await ds.query('SELECT name AS name FROM iam_role WHERE id = ?', [ids[0]]))[0]
    await create({ ...body(unique()), name }).expect(201)
  })

  it('options: enabled rows as { id, code, name } in display order, for any signed-in user; root only for root', async () => {
    const { id } = await add(body(unique(), { enabled: false }))
    const all = await ds.query(
      'SELECT id, code, name AS name FROM iam_role WHERE enabled = 1 AND deleted_at IS NULL ORDER BY sort_no, id',
    )
    const admin = await call('admin', 'get', '/options').expect(200)
    expect(admin.body.data).toEqual(all.map((r: object) => ({ ...r })))
    const res = await call('plain', 'get', '/options').expect(200)
    expect(res.body.data).toEqual(
      admin.body.data.filter((r: { code: string }) => r.code !== 'root'),
    )
    expect(res.body.data.map((r: { id: number }) => r.id)).not.toContain(id)
    await request(app.getHttpServer()).get(`${URL}/options`).expect(401)
  })
})

describe('crud', () => {
  const expectErr = (res: request.Response, status: number, code: string) => {
    expect(res.status).toBe(status)
    expect(res.body.code).toBe(code)
  }
  const rootRole = () => findId(ds.manager, 'iam_role', { code: 'root' }) as Promise<number>
  /** A role granted `perms` (by their action menus), data scope all. */
  async function granted(tag: string, perms: string[], over: object = {}) {
    const id = await insertRow(ds.manager, 'iam_role', {
      code: `${PREFIX}${tag}`,
      name: `${PREFIX}${tag}`,
      data_scope: 'all',
      ...over,
    })
    for (const perm of perms)
      await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [
        id,
        await findId(ds.manager, 'iam_menu', { perms: perm }),
      ])
    return id
  }
  const permVer = async (userId: number) =>
    Number((await redis.get(redisKey('authPermVer', userId))) ?? 0)
  const idOf = async (username: string) =>
    (await findId(ds.manager, 'iam_user', { username: PREFIX + username })) as number

  it('crud: a new role is never builtin and starts with the data scope own_dept; menu / dept links on', async () => {
    const tag = unique()
    const row = await add({ ...body(tag), isBuiltin: true, dataScope: 'all' })
    expect(row).toMatchObject({
      isBuiltin: false,
      dataScope: 'own_dept',
      menuLink: true,
      deptLink: true,
    })
  })

  it('crud: builtin roles keep their code and are never deleted; root is never disabled (422 role_builtin)', async () => {
    const root = await rootRole()
    const builtin = await granted(`builtin-${seq}`, [], { is_builtin: 1 })
    for (const res of [
      await call('admin', 'put', `/${root}`, { code: 'root2' }),
      await call('admin', 'put', `/${root}`, { enabled: false }),
      await call('admin', 'put', `/${root}/enabled`, { enabled: false }),
      await call('admin', 'delete', `/${root}`),
      await call('admin', 'put', `/${builtin}`, { code: `${PREFIX}recoded` }),
      await call('admin', 'delete', `/${builtin}`),
      await call('admin', 'post', '/batch-delete', {
        ids: [(await add(body(unique()))).id, builtin],
      }),
    ]) {
      expectErr(res, 422, Err.IAM_ROLE_BUILTIN.code)
      expect(res.body.msg).toBe(t('zh-CN', Err.IAM_ROLE_BUILTIN.key))
    }
    const rootRow = (await call('admin', 'get', `/${root}`).expect(200)).body.data
    expect(rootRow).toMatchObject({ code: 'root', enabled: true, isBuiltin: true })
    // the rest of a builtin role is editable; root's too, by a root caller (the edit form sends it all back)
    await call('admin', 'put', `/${builtin}`, { name: `${PREFIX}renamed-${seq}` }).expect(200)
    await call('admin', 'put', `/${builtin}/enabled`, { enabled: false }).expect(200)
    const loaded = Object.fromEntries(FORM.map((f) => [f, rootRow[f]]))
    await call('admin', 'put', `/${root}`, loaded).expect(200)
    await call('admin', 'put', `/${root}/enabled`, { enabled: true }).expect(200)
    // a non-root editor leaves the root role alone
    const editor = await user(`editor-${seq}`, [
      await granted(`editor-${seq}`, [rolePerms.view, rolePerms.modify]),
    ])
    const res = await request(app.getHttpServer())
      .put(`${URL}/${root}`)
      .set(bearer(editor))
      .send({ note: 'mine' })
    expectErr(res, 422, Err.IAM_ROLE_BUILTIN.code)
    await request(app.getHttpServer())
      .put(`${URL}/${builtin}`)
      .set(bearer(editor))
      .send({ note: 'fine' })
      .expect(200)
  })

  it('crud: a role that live users hold is not deleted (409 role_has_users, the batch neither); its grants go with it (soft-deleted)', async () => {
    const held = (await add(body(unique()))).id
    const free = (await add(body(unique()))).id
    await user(`member-${seq}`, [held])
    // a link to a deleted user holds nothing (such links may be left by older data: no foreign keys)
    const byGone = (await add(body(unique()))).id
    await user(`gone-${seq}`, [byGone])
    await ds.query('UPDATE iam_user SET deleted_at = NOW(3) WHERE username = ?', [
      `${PREFIX}gone-${seq}`,
    ])
    await call('admin', 'delete', `/${byGone}`).expect(200)
    for (const res of [
      await call('admin', 'delete', `/${held}`),
      await call('admin', 'post', '/batch-delete', { ids: [free, held] }),
    ]) {
      expectErr(res, 409, Err.IAM_ROLE_HAS_USERS.code)
      expect(res.body.msg).toBe(t('zh-CN', Err.IAM_ROLE_HAS_USERS.key))
    }
    await call('admin', 'get', `/${free}`).expect(200)
    // the grants of a deleted role go with it (soft-deleted) and stop blocking their menu's delete
    const menu = await insertRow(ds.manager, 'iam_menu', {
      parent_id: 0,
      kind: 'action',
      name: `${PREFIX}menu-${seq}`,
      perms: `test.roleE2e.m${seq}`,
    })
    const dept = await findId(ds.manager, 'iam_dept', { name: 'seed.dept.rd' })
    await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [free, menu])
    await ds.query('INSERT INTO iam_role_depts (role_id, dept_id) VALUES (?, ?)', [free, dept])
    const deleteMenu = () =>
      request(app.getHttpServer()).delete(`/api/iam/menus/${menu}`).set(bearer(tokens.admin))
    expectErr(await deleteMenu(), 409, Err.IAM_MENU_GRANTED.code)
    await call('admin', 'delete', `/${free}`).expect(200)
    const gone = 'SELECT deleted_at IS NOT NULL AS gone FROM ?? WHERE role_id = ?'
    expect(await ds.query(gone, ['iam_role_menus', free])).toEqual([{ gone: 1 }])
    expect(await ds.query(gone, ['iam_role_depts', free])).toEqual([{ gone: 1 }])
    await deleteMenu().expect(200)
    await ds.query('DELETE FROM iam_menu WHERE id = ?', [menu])
    // once nobody holds it (the link soft-deleted, as a revoke leaves it), it goes
    await ds.query('UPDATE iam_user_roles SET deleted_at = NOW(3) WHERE role_id = ?', [held])
    await call('admin', 'delete', `/${held}`).expect(200)
  })

  it('crud: disabling a role → its users lose its perms at their next request (no new sign-in); enabling gives them back', async () => {
    const role = await granted(`holder-${seq}`, [userPerms.browse])
    const holder = await user(`holder-${seq}`, [role])
    const users = () =>
      request(app.getHttpServer()).get('/api/iam/users').set(bearer(holder)).query({ pageSize: 1 })
    await users().expect(200)
    await call('admin', 'put', `/${role}/enabled`, { enabled: false }).expect(200)
    expectErr(await users(), 403, Err.FORBIDDEN.code)
    await call('admin', 'put', `/${role}`, { enabled: true }).expect(200)
    await users().expect(200)
  })

  it('crud: enabled or code changes reload the holders (bumpUsersOfRole); other edits and refused writes do not', async () => {
    const role = (await add(body(unique()))).id
    await user(`bumped-${seq}`, [role])
    const holder = await idOf(`bumped-${seq}`)
    const bumps = async (write: () => Promise<unknown>) => {
      const before = await permVer(holder)
      await write()
      return (await permVer(holder)) - before
    }
    const put = (path: string, dto: object, status = 200) =>
      bumps(() => call('admin', 'put', path, dto).expect(status))
    expect(await put(`/${role}`, { name: `${PREFIX}renamed-${seq}`, note: 'x' })).toBe(0)
    expect(await put(`/${role}`, { enabled: true })).toBe(0) // unchanged
    expect(await put(`/${role}/enabled`, { enabled: false })).toBe(1)
    expect(await put(`/${role}`, { enabled: true })).toBe(1)
    expect(await put(`/${role}`, { code: `${PREFIX}recoded-${seq}` })).toBe(1)
    const root = await rootRole()
    expect(await put(`/${root}/enabled`, { enabled: false }, 422)).toBe(0)
  })
})

describe('grant', () => {
  const expectErr = (res: request.Response, status: number, code: string) => {
    expect(res.status).toBe(status)
    expect(res.body.code).toBe(code)
  }
  const menuId = async (by: Record<string, string>) =>
    (await findId(ds.manager, 'iam_menu', by)) as number
  const deptId = async (name: string) => (await findId(ds.manager, 'iam_dept', { name })) as number
  /** The path of route names from the top of `/api/auth/menus` to `routeName` (empty: not there). */
  function trail(nodes: MenuNode[], routeName: string): string[] {
    for (const n of nodes) {
      if (n.routeName === routeName) return [routeName]
      const below = trail(n.children, routeName)
      if (below.length) return [n.routeName ?? String(n.id), ...below]
    }
    return []
  }

  it('grant: the menu tree lists every menu (disabled ones too) as a forest; grant perm only', async () => {
    const tree: RoleMenuNode[] = (await call('admin', 'get', '/menu-tree').expect(200)).body.data
    const all = await ds.query('SELECT id FROM iam_menu')
    const flat = (nodes: RoleMenuNode[]): RoleMenuNode[] =>
      nodes.flatMap((n) => [n, ...flat(n.children)])
    expect(
      flat(tree)
        .map((n) => n.id)
        .sort((a, b) => a - b),
    ).toEqual(all.map((r: { id: number }) => Number(r.id)).sort((a: number, b: number) => a - b))
    const iam = tree.find((n) => n.name === 'menu.system.title')!
    const page = iam.children.find((n) => n.name === 'menu.iam.role')!
    // the page's actions, then the hidden members page holding `assign-users`
    const { 'assign-users': assignUsers, ...pagePerms } = rolePerms
    expect(page.children.map((n) => n.perms)).toEqual([...Object.values(pagePerms), null])
    expect(page.children.at(-1)!.children.map((n) => n.perms)).toEqual([assignUsers])
    expect(page).toMatchObject({ kind: 'page', perms: null, enabled: true, nameI18n: null })
    expectErr(await call('reader', 'get', '/menu-tree'), 403, Err.FORBIDDEN.code)
  })

  it("grant: only one action granted (link off) → the role's users get its perm and the whole group → page path at their next request", async () => {
    const role = (await add(body(unique()))).id
    const holder = await member(`granted-${seq}`, [role])
    const users = () => as(holder.token, 'get', '/api/iam/users').query({ pageSize: 1 })
    const menus = async (): Promise<MenuNode[]> =>
      (await as(holder.token, 'get', '/api/auth/menus').expect(200)).body.data
    expectErr(await users(), 403, Err.FORBIDDEN.code)
    expect(trail(await menus(), 'iam-user')).toEqual([])

    const action = await menuId({ perms: userPerms.browse })
    await call('admin', 'put', `/${role}/menus`, { menuLink: false, menuIds: [action] }).expect(200)
    expect((await call('admin', 'get', `/${role}/menus`).expect(200)).body.data).toEqual({
      menuLink: false,
      menuIds: [action],
    })
    await users().expect(200)
    expect(trail(await menus(), 'iam-user')).toEqual(['system', 'iam-user'])
    // cleared again: gone at the next request
    await call('admin', 'put', `/${role}/menus`, { menuLink: false, menuIds: [] }).expect(200)
    expectErr(await users(), 403, Err.FORBIDDEN.code)
  })

  it('grant: the menus are replaced as sent (link on: checked + half-checked), with the link switch', async () => {
    const role = (await add(body(unique()))).id
    const [group, page, browse, view] = [
      await menuId({ route_name: 'system' }),
      await menuId({ route_name: 'iam-user' }),
      await menuId({ perms: userPerms.browse }),
      await menuId({ perms: userPerms.view }),
    ]
    await call('admin', 'put', `/${role}/menus`, {
      menuLink: true,
      menuIds: [view, browse, page, group, view],
    }).expect(200)
    const got = (await call('admin', 'get', `/${role}/menus`).expect(200)).body.data
    expect(got).toEqual({
      menuLink: true,
      menuIds: [group, page, browse, view].sort((a, b) => a - b),
    })
    expect((await call('admin', 'get', `/${role}`)).body.data.menuLink).toBe(true)
    await call('admin', 'put', `/${role}/menus`, { menuLink: false, menuIds: [browse] }).expect(200)
    expect((await call('admin', 'get', `/${role}/menus`)).body.data).toEqual({
      menuLink: false,
      menuIds: [browse],
    })
  })

  it("grant: the data scope and its picked depts reach the holders' lists at their next request; other scopes drop the depts", async () => {
    const role = (await add(body(unique()))).id
    await call('admin', 'put', `/${role}/menus`, {
      menuLink: false,
      menuIds: [await menuId({ perms: userPerms.browse })],
    }).expect(200)
    const [platform, finance] = [
      await deptId('seed.dept.platform'),
      await deptId('seed.dept.finance'),
    ]
    const tag = `scoped-${seq}`
    const holder = await member(`${tag}-holder`, [role], platform)
    await member(`${tag}-mate`, [], platform)
    await member(`${tag}-other`, [], finance)
    const seen = async () =>
      (
        await as(holder.token, 'get', '/api/iam/users')
          .query({ keyword: `${PREFIX}${tag}`, sort: 'username' })
          .expect(200)
      ).body.data.items.map((u: { username: string }) => u.username.slice(PREFIX.length))
    const scope = (dto: object) => call('admin', 'put', `/${role}/data-scope`, dto)

    expect(await seen()).toEqual([`${tag}-holder`, `${tag}-mate`]) // own_dept, the default
    await scope({ dataScope: 'picked_depts', deptLink: false, deptIds: [finance] }).expect(200)
    expect((await call('admin', 'get', `/${role}/data-scope`).expect(200)).body.data).toEqual({
      dataScope: 'picked_depts',
      deptLink: false,
      deptIds: [finance],
    })
    expect(await seen()).toEqual([`${tag}-other`])
    // replaced picks: the dropped dept's link is soft-deleted and reaches nothing any more
    await scope({ dataScope: 'picked_depts', deptLink: false, deptIds: [platform] }).expect(200)
    expect(await seen()).toEqual([`${tag}-holder`, `${tag}-mate`])
    // a deleted dept reaches nothing either, though still picked and with a user left in it (older
    // data: no foreign keys)
    const gone = await insertRow(ds.manager, 'iam_dept', {
      parent_id: 0,
      tree_path: '/',
      name: `${PREFIX}${tag}-dept`,
    })
    await ds.query('UPDATE iam_dept SET tree_path = ? WHERE id = ?', [`/${gone}/`, gone])
    try {
      await member(`${tag}-far`, [], gone)
      await scope({ dataScope: 'picked_depts', deptLink: false, deptIds: [platform, gone] }).expect(
        200,
      )
      expect(await seen()).toEqual([`${tag}-far`, `${tag}-holder`, `${tag}-mate`])
      await ds.query('UPDATE iam_dept SET deleted_at = NOW(3) WHERE id = ?', [gone])
      expect((await call('admin', 'get', `/${role}/data-scope`)).body.data.deptIds).toEqual([
        platform,
      ])
      await app.get(PermVersion).bumpUser(holder.id) // the session reloads its roles
      expect(await seen()).toEqual([`${tag}-holder`, `${tag}-mate`])
    } finally {
      await ds.query('UPDATE iam_user SET deleted_at = NOW(3) WHERE username = ?', [
        `${PREFIX}${tag}-far`,
      ])
      await ds.query('DELETE FROM iam_dept WHERE id = ?', [gone])
    }
    await scope({ dataScope: 'own_rows', deptLink: true, deptIds: [finance] }).expect(200)
    expect((await call('admin', 'get', `/${role}/data-scope`)).body.data).toEqual({
      dataScope: 'own_rows',
      deptLink: true,
      deptIds: [],
    })
    expect(await seen()).toEqual([`${tag}-holder`])
    await scope({ dataScope: 'all', deptLink: true, deptIds: [] }).expect(200)
    expect(await seen()).toEqual([`${tag}-holder`, `${tag}-mate`, `${tag}-other`])
  })

  it('grant: unknown menus or depts 404 (nothing changes), the root role 422, bad bodies 400, grant perm only, action-logged', async () => {
    const role = (await add(body(unique()))).id
    const browse = await menuId({ perms: userPerms.browse })
    await call('admin', 'put', `/${role}/menus`, { menuLink: true, menuIds: [browse] }).expect(200)
    const gone = await insertRow(ds.manager, 'iam_dept', {
      parent_id: 0,
      tree_path: '/',
      name: `${PREFIX}gone-${seq}`,
      deleted_at: new Date(),
    })
    for (const res of [
      await call('admin', 'put', `/${role}/menus`, { menuLink: true, menuIds: [browse, MISSING] }),
      await call('admin', 'put', `/${role}/data-scope`, {
        dataScope: 'picked_depts',
        deptLink: true,
        deptIds: [gone],
      }),
      await call('admin', 'put', `/${MISSING}/menus`, { menuLink: true, menuIds: [] }),
      await call('admin', 'get', `/${MISSING}/menus`),
      await call('admin', 'get', `/${MISSING}/data-scope`),
    ])
      expectErr(res, 404, Err.NOT_FOUND.code)
    await ds.query('DELETE FROM iam_dept WHERE id = ?', [gone])
    expect((await call('admin', 'get', `/${role}/menus`)).body.data.menuIds).toEqual([browse])
    expect((await call('admin', 'get', `/${role}/data-scope`)).body.data.dataScope).toBe('own_dept')

    const root = (await findId(ds.manager, 'iam_role', { code: 'root' })) as number
    expectErr(
      await call('admin', 'put', `/${root}/menus`, { menuLink: true, menuIds: [browse] }),
      422,
      Err.IAM_ROLE_BUILTIN.code,
    )
    expectErr(
      await call('admin', 'put', `/${root}/data-scope`, {
        dataScope: 'own_rows',
        deptLink: true,
        deptIds: [],
      }),
      422,
      Err.IAM_ROLE_BUILTIN.code,
    )
    for (const [path, dto] of [
      ['menus', { menuLink: true }],
      ['menus', { menuLink: true, menuIds: [0] }],
      ['data-scope', { dataScope: 'everything', deptLink: true, deptIds: [] }],
      ['data-scope', { dataScope: 'own_dept', deptIds: [] }],
    ] as const)
      expectErr(
        await call('admin', 'put', `/${role}/${path}`, dto),
        400,
        Err.VALIDATION_FAILED.code,
      )
    for (const res of [
      await call('reader', 'get', `/${role}/menus`),
      await call('reader', 'put', `/${role}/menus`, { menuLink: true, menuIds: [] }),
      await call('reader', 'get', `/${role}/data-scope`),
      await call('reader', 'put', `/${role}/data-scope`, {
        dataScope: 'own_dept',
        deptLink: true,
        deptIds: [],
      }),
    ])
      expectErr(res, 403, Err.FORBIDDEN.code)

    const trace = `${PREFIX}${process.pid}-grant-`
    await call('admin', 'put', `/${role}/menus`, { menuLink: true, menuIds: [] })
      .set('X-Request-Id', `${trace}m`)
      .expect(200)
    await call('admin', 'put', `/${role}/data-scope`, {
      dataScope: 'own_dept',
      deptLink: true,
      deptIds: [],
    })
      .set('X-Request-Id', `${trace}d`)
      .expect(200)
    for (const suffix of ['m', 'd'])
      expect(await logOf(ds, `${trace}${suffix}`)).toMatchObject({
        domain: 'iam.role',
        verb: 'grant',
        biz_id: String(role),
        ok: 1,
      })
  })

  it('grant: menus and data scope reload the holders (bumpUsersOfRole), a refused grant does not', async () => {
    const role = (await add(body(unique()))).id
    const holder = await member(`grant-bump-${seq}`, [role])
    const ver = async () => Number((await redis.get(redisKey('authPermVer', holder.id))) ?? 0)
    const bumps = async (path: string, dto: object, status = 200) => {
      const before = await ver()
      await call('admin', 'put', `/${role}/${path}`, dto).expect(status)
      return (await ver()) - before
    }
    expect(await bumps('menus', { menuLink: true, menuIds: [] })).toBe(1)
    expect(await bumps('data-scope', { dataScope: 'own_rows', deptLink: true, deptIds: [] })).toBe(
      1,
    )
    expect(await bumps('menus', { menuLink: true, menuIds: [MISSING] }, 404)).toBe(0)
  })
})

describe('members', () => {
  const expectErr = (res: request.Response, status: number, code: string) => {
    expect(res.status).toBe(status)
    expect(res.body.code).toBe(code)
  }
  const menuOf = async (perm: string) =>
    (await findId(ds.manager, 'iam_menu', { perms: perm })) as number
  /** A role (data scope `scope`) granted `perms` by their action menus. */
  async function roleWith(tag: string, perms: string[], scope = 'own_dept') {
    const id = await insertRow(ds.manager, 'iam_role', {
      code: `${PREFIX}${tag}`,
      name: `${PREFIX}${tag}`,
      data_scope: scope,
    })
    for (const perm of perms)
      await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [
        id,
        await menuOf(perm),
      ])
    return id
  }
  /** The users holding `role` (live links). */
  const holders = async (role: number) =>
    (
      await ds.query(
        'SELECT user_id AS id FROM iam_user_roles WHERE role_id = ? AND deleted_at IS NULL ORDER BY user_id',
        [role],
      )
    ).map((r: { id: number }) => Number(r.id))
  /** Every link row of `role` (revoked ones stay, soft-deleted): `[user id, live]`. */
  const links = async (role: number) =>
    (
      await ds.query<{ id: number; live: number }[]>(
        'SELECT user_id AS id, deleted_at IS NULL AS live FROM iam_user_roles WHERE role_id = ? ORDER BY 1',
        [role],
      )
    ).map((r): [number, boolean] => [Number(r.id), Number(r.live) === 1])
  const ver = async (userId: number) =>
    Number((await redis.get(redisKey('authPermVer', userId))) ?? 0)

  /**
   * An own_dept operator (members + user list) in the platform dept, the role R it manages (the user list,
   * own_dept) and users: A (platform, holds R), B and E (platform), C (finance), D (finance, holds R).
   */
  async function setup() {
    const tag = `m${++seq}`
    const [platform, finance] = [
      (await findId(ds.manager, 'iam_dept', { name: 'seed.dept.platform' })) as number,
      (await findId(ds.manager, 'iam_dept', { name: 'seed.dept.finance' })) as number,
    ]
    const R = await roleWith(`${tag}-r`, [userPerms.browse])
    const opRole = await roleWith(`${tag}-op`, [rolePerms['assign-users'], userPerms.browse])
    const op = await member(`${tag}-op`, [opRole], platform)
    const [A, B, C, D, E] = [
      await member(`${tag}-a`, [R], platform),
      await member(`${tag}-b`, [], platform),
      await member(`${tag}-c`, [], finance),
      await member(`${tag}-d`, [R], finance),
      await member(`${tag}-e`, [], platform),
    ]
    const as = (method: 'get' | 'post', path: string, token = op.token) =>
      request(app.getHttpServer())[method](`${URL}/${R}/members${path}`).set(bearer(token))
    const names = (res: request.Response) =>
      res.body.data.items.map((u: { username: string }) =>
        u.username.slice(PREFIX.length + tag.length + 1),
      )
    return { tag, R, op, A, B, C, D, E, as, names }
  }

  it("members: both lists go through the caller's iam_user scope (out-of-scope users never listed), filtered and paged", async () => {
    const { tag, R, as, names } = await setup()
    const list = (assigned: boolean, query: object = {}) =>
      as('get', '')
        .query({ assigned, keyword: `${PREFIX}${tag}`, sort: 'username', ...query })
        .expect(200)
    expect(names(await list(true))).toEqual(['a'])
    expect(names(await list(false))).toEqual(['b', 'e', 'op'])
    const page = await list(false, { pageSize: 1, page: 2 })
    expect(names(page)).toEqual(['e'])
    expect(page.body.data.total).toBe(3)
    expect(names(await list(false, { keyword: `${PREFIX}${tag}-b` }))).toEqual(['b'])
    expect((await list(true)).body.data.items[0]).toMatchObject({
      deptName: 'seed.dept.platform',
      enabled: true,
      createdAt: expect.any(String),
    })
    // assigned is the default; root sees everyone
    expect(
      names(
        await as('get', '')
          .query({ keyword: `${PREFIX}${tag}` })
          .expect(200),
      ),
    ).toEqual(['a'])
    const all = await call('admin', 'get', `/${R}/members`)
      .query({ assigned: false, keyword: `${PREFIX}${tag}`, sort: 'username' })
      .expect(200)
    expect(names(all)).toEqual(['b', 'c', 'e', 'op'])
  })

  it('members: add / revoke — out-of-scope users 404 and nothing changes; the changed users get it at their next request', async () => {
    const { R, A, B, C, D, E, as } = await setup()
    const users = (token: string) =>
      request(app.getHttpServer()).get('/api/iam/users').set(bearer(token)).query({ pageSize: 1 })
    expectErr(await users(B.token), 403, Err.FORBIDDEN.code)

    const before = { a: await ver(A.id), b: await ver(B.id) }
    await as('post', '')
      .send({ userIds: [B.id, A.id] })
      .expect(200)
    expect(await holders(R)).toEqual([A.id, B.id, D.id].sort((x, y) => x - y))
    expect(await ver(B.id)).toBe(before.b + 1)
    expect(await ver(A.id)).toBe(before.a) // held it already
    await users(B.token).expect(200)

    for (const res of [
      await as('post', '').send({ userIds: [E.id, C.id] }),
      await as('post', '/revoke').send({ userIds: [D.id] }),
      await as('post', '/revoke').send({ userIds: [A.id, D.id] }),
    ])
      expectErr(res, 404, Err.NOT_FOUND.code)
    expect(await holders(R)).toEqual([A.id, B.id, D.id].sort((x, y) => x - y))

    await as('post', '/revoke')
      .send({ userIds: [B.id, E.id] })
      .expect(200)
    expect(await holders(R)).toEqual([A.id, D.id].sort((x, y) => x - y))
    expectErr(await users(B.token), 403, Err.FORBIDDEN.code)
    const listed = async (assigned: boolean) =>
      (await as('get', '').query({ assigned, pageSize: 100 }).expect(200)).body.data.items.map(
        (u: { id: number }) => u.id,
      )
    expect(await listed(true)).not.toContain(B.id)
    expect(await listed(false)).toContain(B.id)
    // the revoked link stays as a soft-deleted row; adding B again revives it (one row per pair)
    const byUser = (rows: [number, boolean][]) => rows.find(([id]) => id === B.id)
    expect(byUser(await links(R))).toEqual([B.id, false])
    await as('post', '')
      .send({ userIds: [B.id] })
      .expect(200)
    expect(byUser(await links(R))).toEqual([B.id, true])
    expect((await links(R)).filter(([id]) => id === B.id)).toHaveLength(1)
    await users(B.token).expect(200)
  })

  it('members: GrantPolicy guards adds (403), nobody leaves the root role and non-root callers leave root users alone (422), unknown role 404, 400, assign-users only, action-logged', async () => {
    const { R, op, B, as } = await setup()
    const root = (await findId(ds.manager, 'iam_role', { code: 'root' })) as number
    const wider = await roleWith(`wider-${seq}`, [rolePerms.remove])
    for (const role of [root, wider])
      expectErr(
        await request(app.getHttpServer())
          .post(`${URL}/${role}/members`)
          .set(bearer(op.token))
          .send({ userIds: [B.id] }),
        403,
        Err.IAM_GRANT_EXCEEDS_OWN.code,
      )
    const admin = (await findId(ds.manager, 'iam_user', { username: 'admin' })) as number
    expectErr(
      await call('admin', 'post', `/${root}/members/revoke`, { userIds: [admin] }),
      422,
      Err.IAM_USER_PROTECTED.code,
    )
    expect(await holders(root)).toContain(admin)
    // a root user in the operator's scope keeps its roles as they are (a root caller may change them)
    const platform = (await findId(ds.manager, 'iam_dept', {
      name: 'seed.dept.platform',
    })) as number
    const [held, bare] = [
      await member(`root-held-${seq}`, [root, R], platform),
      await member(`root-bare-${seq}`, [root], platform),
    ]
    for (const res of [
      await as('post', '/revoke').send({ userIds: [held.id] }),
      await as('post', '').send({ userIds: [bare.id] }),
    ])
      expectErr(res, 422, Err.IAM_USER_PROTECTED.code)
    expect(await holders(R)).toContain(held.id)
    expect(await holders(R)).not.toContain(bare.id)
    await call('admin', 'post', `/${R}/members`, { userIds: [bare.id] }).expect(200)
    await call('admin', 'post', `/${R}/members/revoke`, { userIds: [held.id, bare.id] }).expect(200)
    for (const res of [
      await call('admin', 'get', `/${MISSING}/members`),
      await call('admin', 'post', `/${MISSING}/members`, { userIds: [B.id] }),
      await call('admin', 'post', `/${MISSING}/members/revoke`, { userIds: [B.id] }),
      await call('admin', 'post', `/${R}/members`, { userIds: [MISSING] }),
    ])
      expectErr(res, 404, Err.NOT_FOUND.code)
    for (const dto of [{ userIds: [] }, { userIds: ['x'] }, {}])
      expectErr(await as('post', '').send(dto), 400, Err.VALIDATION_FAILED.code)
    await as('get', '').query({ assigned: 'maybe' }).expect(400)
    for (const res of [
      await call('reader', 'get', `/${R}/members`),
      await call('reader', 'post', `/${R}/members`, { userIds: [B.id] }),
      await call('reader', 'post', `/${R}/members/revoke`, { userIds: [B.id] }),
    ])
      expectErr(res, 403, Err.FORBIDDEN.code)

    const trace = `${PREFIX}${process.pid}-members-`
    await as('post', '')
      .send({ userIds: [B.id] })
      .set('X-Request-Id', `${trace}g`)
      .expect(200)
    await as('post', '/revoke')
      .send({ userIds: [B.id] })
      .set('X-Request-Id', `${trace}r`)
      .expect(200)
    for (const [suffix, verb] of [
      ['g', 'grant'],
      ['r', 'revoke'],
    ])
      expect(await logOf(ds, `${trace}${suffix}`)).toMatchObject({
        domain: 'iam.role',
        verb,
        biz_id: String(R),
        ok: 1,
      })
  })
})

describe('escalation', () => {
  const refused = (res: request.Response) => {
    expect(res.status).toBe(403)
    expect(res.body.code).toBe(Err.IAM_GRANT_EXCEEDS_OWN.code)
  }
  const menuOf = async (perm: string) =>
    (await findId(ds.manager, 'iam_menu', { perms: perm })) as number
  const deptOf = async (name: string) =>
    (await findId(ds.manager, 'iam_dept', { name: `seed.dept.${name}` })) as number
  /** A role of scope `scope` (its picked depts `depts`) granted `perms` by their action menus. */
  async function roleWith(tag: string, perms: string[], scope = 'own_dept', depts: number[] = []) {
    const id = await insertRow(ds.manager, 'iam_role', {
      code: `${PREFIX}${tag}`,
      name: `${PREFIX}${tag}`,
      data_scope: scope,
    })
    for (const perm of perms)
      await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [
        id,
        await menuOf(perm),
      ])
    for (const dept of depts)
      await ds.query('INSERT INTO iam_role_depts (role_id, dept_id) VALUES (?, ?)', [id, dept])
    return id
  }
  const grants = async (role: number) => ({
    menus: (await call('admin', 'get', `/${role}/menus`).expect(200)).body.data.menuIds,
    scope: (await call('admin', 'get', `/${role}/data-scope`).expect(200)).body.data,
  })
  const rolesOf = async (user: number) =>
    (
      await ds.query(
        'SELECT role_id AS id FROM iam_user_roles WHERE user_id = ? AND deleted_at IS NULL ORDER BY 1',
        [user],
      )
    ).map((r: { id: number }) => Number(r.id))

  it('keeps the sign-up role root-managed across direct, member and indirect menu writes; sign-up uses its id', async () => {
    const memberId = Number(
      (
        await ds.query('SELECT param_value FROM cfg_param WHERE param_key = ?', [
          signupParams.defaultRoleId,
        ])
      )[0].param_value,
    )
    const [original] = await ds.query(
      'SELECT code, name, enabled, data_scope FROM iam_role WHERE id = ?',
      [memberId],
    )
    const originalMenus = (await grants(memberId)).menus
    const ordinary = await roleWith(`signup-ordinary-${++seq}`, [], 'own_rows')
    const ordinaryCode = (await ds.query('SELECT code FROM iam_role WHERE id = ?', [ordinary]))[0]
      .code as string
    const operatorRole = await roleWith(
      `signup-operator-${seq}`,
      [...Object.values(rolePerms), menuPerms.modify],
      'all',
    )
    const operator = await member(`signup-operator-${seq}`, [operatorRole])
    const target = await member(`signup-target-${seq}`, [])
    const home = await findId(ds.manager, 'iam_menu', { route_name: 'home' })
    const action = (
      await request(app.getHttpServer())
        .post('/api/iam/menus')
        .set(bearer(tokens.admin))
        .send({
          kind: 'action',
          name: unique(),
          parentId: home,
          perms: rolePerms.browse,
        })
        .expect(201)
    ).body.data.id as number
    const menu = (id: number, perms: string, token = operator.token) =>
      request(app.getHttpServer()).put(`/api/iam/menus/${id}`).set(bearer(token)).send({ perms })
    const write = (
      method: 'put' | 'post' | 'delete',
      path: string,
      dto?: object,
      token = operator.token,
    ) => {
      const req = request(app.getHttpServer())[method](`${URL}${path}`).set(bearer(token))
      return dto ? req.send(dto) : req
    }
    const params = app.get(ParamService)
    const switchRow = (
      await ds.query('SELECT param_value FROM cfg_param WHERE param_key = ?', [
        signupParams.enabled,
      ])
    )[0].param_value as string
    try {
      for (const dto of [
        { code: unique() },
        { name: unique() },
        { sortNo: 123 },
        { note: 'blocked' },
        { enabled: false },
      ])
        refused(await write('put', `/${memberId}`, dto))
      for (const enabled of [false, true])
        refused(await write('put', `/${memberId}/enabled`, { enabled }))
      refused(
        await write('put', `/${memberId}/menus`, {
          menuLink: false,
          menuIds: [...originalMenus, action],
        }),
      )
      for (const scope of [
        { dataScope: 'own_dept_tree', deptLink: false, deptIds: [] },
        { dataScope: 'picked_depts', deptLink: false, deptIds: [await deptOf('rd')] },
      ])
        refused(await write('put', `/${memberId}/data-scope`, scope))
      refused(await write('delete', `/${memberId}`))
      refused(await write('post', '/batch-delete', { ids: [ordinary, memberId] }))
      refused(await write('post', `/${memberId}/members`, { userIds: [target.id] }))
      const held = await member(`signup-held-${seq}`, [memberId])
      refused(await write('post', `/${memberId}/members/revoke`, { userIds: [held.id] }))
      expect(
        (
          await ds.query('SELECT code, name, enabled, data_scope FROM iam_role WHERE id = ?', [
            memberId,
          ])
        )[0],
      ).toEqual(original)
      expect((await grants(memberId)).menus).toEqual(originalMenus)
      expect((await grants(memberId)).scope).toMatchObject({
        dataScope: original.data_scope,
        deptIds: [],
      })
      expect(await rolesOf(target.id)).toEqual([])
      expect(await rolesOf(held.id)).toEqual([memberId])
      expect(
        (await ds.query('SELECT deleted_at FROM iam_role WHERE id = ?', [ordinary]))[0].deleted_at,
      ).toBeNull()

      await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [
        memberId,
        action,
      ])
      refused(await menu(action, rolePerms.modify))
      expect((await ds.query('SELECT perms FROM iam_menu WHERE id = ?', [action]))[0].perms).toBe(
        rolePerms.browse,
      )
      await ds.query('DELETE FROM iam_role_menus WHERE role_id = ? AND menu_id = ?', [
        memberId,
        action,
      ])

      await write('put', `/${ordinary}`, { name: unique() }).expect(200)
      await write('put', `/${ordinary}`, { code: unique() }).expect(200)
      await write('put', `/${ordinary}/enabled`, { enabled: false }).expect(200)
      await write('put', `/${ordinary}/enabled`, { enabled: true }).expect(200)
      await write('put', `/${ordinary}/menus`, { menuLink: false, menuIds: [action] }).expect(200)
      await write('put', `/${ordinary}/data-scope`, {
        dataScope: 'own_dept_tree',
        deptLink: false,
        deptIds: [],
      }).expect(200)
      await write('post', `/${ordinary}/members`, { userIds: [target.id] }).expect(200)
      await write('post', `/${ordinary}/members/revoke`, { userIds: [target.id] }).expect(200)
      await menu(action, rolePerms.modify).expect(200)
      const removable = await roleWith(`signup-removable-${seq}`, [])
      await write('delete', `/${removable}`).expect(200)

      await write('put', `/${memberId}`, { name: unique() }, tokens.admin).expect(200)
      await write(
        'put',
        `/${memberId}/menus`,
        { menuLink: false, menuIds: [...originalMenus, action] },
        tokens.admin,
      ).expect(200)
      await write(
        'put',
        `/${memberId}/menus`,
        { menuLink: false, menuIds: originalMenus },
        tokens.admin,
      ).expect(200)
      await write(
        'put',
        `/${memberId}/data-scope`,
        { dataScope: 'own_rows', deptLink: false, deptIds: [] },
        tokens.admin,
      ).expect(200)
      await write('post', `/${memberId}/members`, { userIds: [target.id] }, tokens.admin).expect(
        200,
      )
      await write(
        'post',
        `/${memberId}/members/revoke`,
        { userIds: [target.id] },
        tokens.admin,
      ).expect(200)
      await write('put', `/${memberId}`, { code: `${PREFIX}moved-${seq}` }, tokens.admin).expect(
        200,
      )
      await write('put', `/${ordinary}`, { code: 'member' }, tokens.admin).expect(200)
      await ds.query('UPDATE cfg_param SET param_value = ? WHERE param_key = ?', [
        'true',
        signupParams.enabled,
      ])
      await params.invalidate(signupParams.enabled)
      const username = `${PREFIX}signed-${seq}`
      await request(app.getHttpServer())
        .post('/api/auth/signup')
        .send({ username, password: 'Signup#Pass2026' })
        .expect(201)
      const signed = Number(
        (await ds.query('SELECT id FROM iam_user WHERE username = ?', [username]))[0].id,
      )
      userIds.push(signed)
      expect(await rolesOf(signed)).toEqual([memberId])
    } finally {
      await ds.query('UPDATE cfg_param SET param_value = ? WHERE param_key = ?', [
        switchRow,
        signupParams.enabled,
      ])
      await params.invalidate(signupParams.enabled)
      await ds.query('UPDATE iam_role SET code = ? WHERE id = ?', [ordinaryCode, ordinary])
      await ds.query(
        'UPDATE iam_role SET code = ?, name = ?, enabled = ?, data_scope = ? WHERE id = ?',
        [original.code, original.name, original.enabled, original.data_scope, memberId],
      )
      await ds.query('DELETE FROM iam_role_menus WHERE menu_id = ?', [action])
      await ds.query('DELETE FROM iam_menu WHERE id = ?', [action])
    }
  })

  /**
   * The operator: in R&D, granting roles and managing users over R&D and below (platform, product), but
   * viewing users in R&D only (a narrower scope for `iam.user.view`); outside it: finance, ops, HQ.
   */
  async function setup() {
    const tag = `x${++seq}`
    const dept = {
      rd: await deptOf('rd'),
      platform: await deptOf('platform'),
      product: await deptOf('product'),
      finance: await deptOf('finance'),
    }
    const manage = await roleWith(
      `${tag}-op`,
      [
        rolePerms.grant,
        rolePerms['assign-users'],
        userPerms.browse,
        userPerms.modify,
        userPerms['assign-roles'],
      ],
      'own_dept_tree',
    )
    const view = await roleWith(`${tag}-op-view`, [userPerms.view], 'own_dept')
    const op = await member(`${tag}-op`, [manage, view], dept.rd)
    const target = await member(`${tag}-target`, [], dept.platform)
    const as = (method: 'put' | 'post', path: string, dto: object, token = op.token) =>
      request(app.getHttpServer())[method](path).set(bearer(token)).send(dto)
    return { tag, dept, op, target, as }
  }

  it('escalation ①: the menu grant refuses a perm the caller lacks, or a perm it holds over a wider scope than its own (picked depts, holders outside); root may', async () => {
    const { tag, dept, as } = await setup()
    const [browse, remove] = [await menuOf(userPerms.browse), await menuOf(rolePerms.remove)]
    const menus = (role: number, menuIds: number[], token?: string) =>
      as('put', `${URL}/${role}/menus`, { menuLink: false, menuIds }, token)
    const bare = await roleWith(`${tag}-bare`, [])
    // a perm the caller lacks (the add is judged whatever it was saved with before)
    refused(await menus(bare, [browse, remove]))
    // a perm it holds, on a role reaching beyond its scope: picked finance (whoever holds it), an own_dept
    // role held by a finance user
    const pickedOut = await roleWith(`${tag}-picked-out`, [], 'picked_depts', [dept.finance])
    const heldOut = await roleWith(`${tag}-held-out`, [])
    await member(`${tag}-finance`, [heldOut], dept.finance)
    refused(await menus(pickedOut, [browse]))
    refused(await menus(heldOut, [browse]))
    // a role of scope all takes no new perm from a non-root caller
    const wide = await roleWith(`${tag}-wide`, [], 'all')
    refused(await menus(wide, [browse]))
    // the same perm on a disabled menu of the role does not make it "kept": enabling it is judged too
    const disabled = await insertRow(ds.manager, 'iam_menu', {
      parent_id: await findId(ds.manager, 'iam_menu', { route_name: 'iam-user' }),
      kind: 'action',
      name: `${PREFIX}${tag}-disabled`,
      perms: userPerms.browse,
      enabled: 0,
    })
    await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [
      pickedOut,
      disabled,
    ])
    refused(await menus(pickedOut, [disabled, browse]))
    expect((await grants(pickedOut)).menus).toEqual([disabled])
    await menus(pickedOut, [], tokens.admin).expect(200)
    await ds.query('DELETE FROM iam_menu WHERE id = ?', [disabled])
    for (const role of [bare, pickedOut, heldOut, wide])
      expect((await grants(role)).menus).toEqual([])

    // within its perms and scope: fine; so is keeping what a root caller granted, and removing it
    const heldIn = await roleWith(`${tag}-held-in`, [rolePerms.remove])
    await member(`${tag}-platform`, [heldIn], dept.platform)
    await menus(heldIn, [remove, browse]).expect(200)
    await menus(heldIn, [browse]).expect(200)
    expect((await grants(heldIn)).menus).toEqual([browse])

    // root: the same grants succeed
    for (const role of [bare, pickedOut, heldOut, wide])
      await menus(role, [browse, remove], tokens.admin).expect(200)
  })

  it('escalation ②: the data scope refuses all, picked depts outside the caller scope of any perm the role carries, and a relative scope reaching holders outside; narrowing passes; root may', async () => {
    const { tag, dept, as } = await setup()
    const scope = (role: number, dataScope: string, deptIds: number[] = [], token?: string) =>
      as('put', `${URL}/${role}/data-scope`, { dataScope, deptLink: false, deptIds }, token)
    const role = await roleWith(`${tag}-browse`, [userPerms.browse])
    refused(await scope(role, 'all'))
    refused(await scope(role, 'picked_depts', [dept.product, dept.finance]))
    await scope(role, 'picked_depts', [dept.platform, dept.product]).expect(200)
    // per perm point: platform is inside the route's scope, not inside the caller's iam.user.view one
    const viewer = await roleWith(`${tag}-view`, [userPerms.view])
    refused(await scope(viewer, 'picked_depts', [dept.platform]))
    await scope(viewer, 'picked_depts', [dept.rd]).expect(200)
    expect((await grants(viewer)).scope).toMatchObject({
      dataScope: 'picked_depts',
      deptIds: [dept.rd],
    })

    // relative scopes reach the holders' depts: a finance holder is outside
    const held = await roleWith(`${tag}-held`, [userPerms.browse], 'own_rows')
    await member(`${tag}-finance`, [held], dept.finance)
    refused(await scope(held, 'own_dept'))
    refused(await scope(held, 'own_dept_tree'))
    expect((await grants(held)).scope.dataScope).toBe('own_rows')
    // narrowing adds nothing: a root-set picked finance may shrink to own_rows, all to own_dept
    const narrowed = await roleWith(`${tag}-narrowed`, [userPerms.browse], 'all')
    await member(`${tag}-finance-2`, [narrowed], dept.finance)
    await scope(narrowed, 'own_dept').expect(200)
    await scope(narrowed, 'own_rows').expect(200)
    // … and the root-set subtree of a finance holder may shrink to picked finance (nothing new to anyone)
    await scope(narrowed, 'own_dept_tree', [], tokens.admin).expect(200)
    await scope(narrowed, 'picked_depts', [dept.finance]).expect(200)
    refused(await scope(narrowed, 'picked_depts', [dept.finance, await deptOf('ops')]))
    const unheld = await roleWith(`${tag}-unheld`, [userPerms.browse], 'all')
    await scope(unheld, 'picked_depts', [dept.finance]).expect(200)
    refused(await scope(unheld, 'picked_depts', [dept.finance, await deptOf('ops')]))

    // root: the same scopes succeed
    await scope(role, 'all', [], tokens.admin).expect(200)
    await scope(viewer, 'picked_depts', [dept.finance], tokens.admin).expect(200)
    await scope(held, 'own_dept_tree', [], tokens.admin).expect(200)
  })

  it('escalation ③: roles given to users through user edit, assign roles and role members refuse a perm the caller lacks and the same perms over scope all or picked depts outside; root may', async () => {
    const { tag, dept, target, as } = await setup()
    const bad = {
      extraPerm: await roleWith(`${tag}-extra`, [userPerms.browse, rolePerms.remove]),
      wide: await roleWith(`${tag}-wide`, [userPerms.browse], 'all'),
      pickedOut: await roleWith(`${tag}-out`, [userPerms.browse], 'picked_depts', [dept.finance]),
    }
    const fine = await roleWith(`${tag}-in`, [userPerms.browse], 'picked_depts', [dept.product])
    const entries = {
      edit: (role: number, token?: string) =>
        as('put', `/api/iam/users/${target.id}`, { roleIds: [role] }, token),
      assignRoles: (role: number, token?: string) =>
        as('put', `/api/iam/users/${target.id}/roles`, { roleIds: [role] }, token),
      members: (role: number, token?: string) =>
        as('post', `${URL}/${role}/members`, { userIds: [target.id] }, token),
    }
    for (const [entry, give] of Object.entries(entries))
      for (const [kind, role] of Object.entries(bad)) {
        const res = await give(role)
        expect([entry, kind, res.status]).toEqual([entry, kind, 403])
        refused(res)
      }
    expect(await rolesOf(target.id)).toEqual([])
    await entries.members(fine).expect(200)
    expect(await rolesOf(target.id)).toEqual([fine])

    // root: every entry gives each of them
    for (const give of Object.values(entries))
      for (const role of Object.values(bad)) {
        await call('admin', 'post', `/${role}/members/revoke`, { userIds: [target.id] })
        await give(role, tokens.admin).expect(200)
        expect(await rolesOf(target.id)).toContain(role)
      }
  })

  it('escalation ④: a menu edit making a perm effective for a role is a grant — enabling the menu or an ancestor, moving it out of a disabled branch, new perms — refused beyond the caller; root may', async () => {
    const { tag, dept } = await setup()
    // a menu editor holding iam.user.browse over R&D and below
    const editor = await roleWith(
      `${tag}-menu-op`,
      [menuPerms.modify, userPerms.browse],
      'own_dept_tree',
    )
    const op = await member(`${tag}-menu-op`, [editor], dept.rd)
    const menus: number[] = []
    const addMenu = async (dto: object) => {
      const res = await request(app.getHttpServer())
        .post('/api/iam/menus')
        .set(bearer(tokens.admin))
        .send(dto)
        .expect(201)
      menus.push(res.body.data.id)
      return res.body.data.id as number
    }
    /** An enabled group → page → action (`perms`) of its own, granted to `roles`; returns their ids. */
    const branch = async (perms: string, roles: number[]) => {
      const name = `${tag}-${menus.length}`
      const group = await addMenu({ kind: 'group', name, routePath: `/${name}`, routeName: name })
      const page = await addMenu({
        kind: 'page',
        name: `${name}-p`,
        routePath: `/${name}-p`,
        routeName: `${name}-p`,
        component: 'home/index',
        parentId: group,
      })
      const action = await addMenu({ kind: 'action', name: `${name}-a`, perms, parentId: page })
      for (const role of roles)
        await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [
          role,
          action,
        ])
      return { group, page, action }
    }
    const menu = (id: number, dto: object, token = op.token) =>
      request(app.getHttpServer()).put(`/api/iam/menus/${id}`).set(bearer(token)).send(dto)
    const enable = (id: number, enabled: boolean, token = op.token) =>
      request(app.getHttpServer())
        .put(`/api/iam/menus/${id}/enabled`)
        .set(bearer(token))
        .send({ enabled })
    const menuRow = async (id: number) =>
      (await ds.query('SELECT enabled, parent_id, perms FROM iam_menu WHERE id = ?', [id]))[0]

    // roles reaching beyond the operator: picked finance (whoever holds it), own_dept held in finance;
    // a fresh one per case (a perm the role already gets elsewhere is nothing new)
    let n = 0
    const pickedOut = () => roleWith(`${tag}-m-picked-${++n}`, [], 'picked_depts', [dept.finance])
    const heldOut = await roleWith(`${tag}-m-held-out`, [])
    await member(`${tag}-m-finance`, [heldOut], dept.finance)
    // … and one inside it: own_dept held in platform
    const heldIn = await roleWith(`${tag}-m-held-in`, [])
    await member(`${tag}-m-platform`, [heldIn], dept.platform)
    try {
      // enabling a disabled menu granted to a wider role (its perm held by the operator) → 403
      for (const role of [await pickedOut(), heldOut]) {
        const { action } = await branch(userPerms.browse, [role])
        await enable(action, false, tokens.admin).expect(200)
        refused(await enable(action, true))
        refused(await menu(action, { enabled: true }))
        expect(Number((await menuRow(action)).enabled)).toBe(0)
        await enable(action, true, tokens.admin).expect(200)
      }
      // … or a perm the operator lacks, even for a role inside its scope
      const lacking = await branch(rolePerms.remove, [heldIn])
      await enable(lacking.action, false, tokens.admin).expect(200)
      refused(await enable(lacking.action, true))
      // inside its perms and scope: fine
      const inside = await branch(userPerms.browse, [heldIn])
      await enable(inside.action, false, tokens.admin).expect(200)
      await enable(inside.action, true).expect(200)

      // enabling a disabled ancestor re-activates the subtree's grants → 403; root may
      const hidden = await branch(userPerms.browse, [await pickedOut()])
      await enable(hidden.group, false, tokens.admin).expect(200)
      refused(await enable(hidden.group, true))
      expect(Number((await menuRow(hidden.group)).enabled)).toBe(0)

      // moving a page out of a disabled branch into an enabled one → 403; root may
      const moved = await branch(userPerms.browse, [await pickedOut()])
      await enable(moved.group, false, tokens.admin).expect(200)
      const target = await addMenu({
        kind: 'group',
        name: `${tag}-target`,
        routePath: `/${tag}-target`,
        routeName: `${tag}-target`,
      })
      refused(await menu(moved.page, { parentId: target }))
      expect(Number((await menuRow(moved.page)).parent_id)).toBe(moved.group)

      // a perm the operator holds put on a menu granted to a wider role → 403; root may
      const recoded = await branch(`e2e.role-${tag}.run`, [await pickedOut()])
      refused(await menu(recoded.action, { perms: userPerms.browse }))
      expect((await menuRow(recoded.action)).perms).toBe(`e2e.role-${tag}.run`)
      // … on one granted inside its scope: fine
      const recodedIn = await branch(`e2e.role-${tag}.in`, [heldIn])
      await menu(recodedIn.action, { perms: userPerms.browse }).expect(200)

      // root: the same edits succeed
      await enable(hidden.group, true, tokens.admin).expect(200)
      await menu(moved.page, { parentId: target }, tokens.admin).expect(200)
      await menu(recoded.action, { perms: userPerms.browse }, tokens.admin).expect(200)
      await enable(lacking.action, true, tokens.admin).expect(200)
    } finally {
      await ds.query('DELETE FROM iam_role_menus WHERE menu_id IN (?)', [menus])
      await ds.query('DELETE FROM iam_menu WHERE id IN (?)', [menus])
    }
  })

  it('escalation ⑤: enabling a role hands out its whole grant — refused when its perms or data scope exceed the caller (disabling passes); root may', async () => {
    const { tag, dept } = await setup()
    const modifier = await roleWith(
      `${tag}-role-op`,
      [rolePerms.modify, userPerms.browse],
      'own_dept_tree',
    )
    const op = await member(`${tag}-role-op`, [modifier], dept.rd)
    const toggle = (role: number, enabled: boolean, token = op.token) =>
      request(app.getHttpServer())
        .put(`${URL}/${role}/enabled`)
        .set(bearer(token))
        .send({ enabled })
    const enabledOf = async (role: number) =>
      Number((await ds.query('SELECT enabled FROM iam_role WHERE id = ?', [role]))[0].enabled)
    const bad = {
      extraPerm: await roleWith(`${tag}-e-extra`, [userPerms.browse, rolePerms.remove]),
      wide: await roleWith(`${tag}-e-wide`, [userPerms.browse], 'all'),
      pickedOut: await roleWith(`${tag}-e-out`, [userPerms.browse], 'picked_depts', [dept.finance]),
      heldOut: await roleWith(`${tag}-e-held-out`, [userPerms.browse]),
    }
    await member(`${tag}-e-finance`, [bad.heldOut], dept.finance)
    const fine = await roleWith(`${tag}-e-in`, [userPerms.browse])
    await member(`${tag}-e-platform`, [fine], dept.platform)

    for (const [kind, role] of Object.entries(bad)) {
      // disabling takes grants away: always allowed
      await toggle(role, false).expect(200)
      const res = await toggle(role, true)
      expect([kind, res.status]).toEqual([kind, 403])
      refused(res)
      // the edit form's PUT /:id enables too
      refused(
        await request(app.getHttpServer())
          .put(`${URL}/${role}`)
          .set(bearer(op.token))
          .send({ enabled: true }),
      )
      expect([kind, await enabledOf(role)]).toEqual([kind, 0])
    }
    await toggle(fine, false).expect(200)
    await toggle(fine, true).expect(200)
    expect(await enabledOf(fine)).toBe(1)

    // root: every one of them enables
    for (const role of Object.values(bad)) {
      await toggle(role, true, tokens.admin).expect(200)
      expect(await enabledOf(role)).toBe(1)
    }
  })
})

describe('errors', () => {
  it('403 per permission: browse-only may list, not view/create/modify/delete; no perm → no list', async () => {
    const { id } = await add(body(unique()))
    await call('reader', 'get').expect(200)
    const forbidden = [
      call('reader', 'get', `/${id}`),
      call('reader', 'post', '', body(unique())),
      call('reader', 'put', `/${id}`, {}),
      call('reader', 'put', `/${id}/enabled`, { enabled: false }),
      call('reader', 'delete', `/${id}`),
      call('reader', 'post', '/batch-delete', { ids: [id] }),
      call('plain', 'get'),
    ]
    for (const res of await Promise.all(forbidden)) {
      expect(res.status).toBe(403)
      expect(res.body.code).toBe(Err.FORBIDDEN.code)
    }
  })

  it('400: invalid body / query / id, with translated field messages', async () => {
    const { id } = await add(body(unique()))
    const required = (lang: string, field: string) =>
      t(lang, 'validation.required', { field: label(lang, field) })
    expect(label('zh-CN', 'name')).not.toMatch(/^field\./)
    expect(label('en-US', 'name')).not.toMatch(/^field\./)
    const zh = await create({ ...body(unique()), name: '', code: 'x'.repeat(65) }).expect(400)
    expect(zh.body).toMatchObject({
      code: Err.VALIDATION_FAILED.code,
      msg: required('zh-CN', 'name'),
    })
    expect(zh.body.errors).toEqual([
      { path: 'name', msg: required('zh-CN', 'name') },
      {
        path: 'code',
        msg: t('zh-CN', 'validation.too_big.string', {
          field: label('zh-CN', 'code'),
          maximum: 64,
        }),
      },
    ])
    const { name: _, ...keyless } = body(unique())
    const en = await create(keyless).set('Accept-Language', 'en-US').expect(400)
    expect(en.body.errors).toEqual([{ path: 'name', msg: required('en-US', 'name') }])
    await call('admin', 'get').query({ sort: 'enabled' }).expect(400)
    await call('admin', 'put', `/${id}/enabled`, { enabled: 'no' }).expect(400)
    await call('admin', 'post', '/batch-delete', { ids: [] }).expect(400)
    await call('admin', 'get', '/abc').expect(400)
  })

  it('409 duplicate: a unique value already taken (create and update; case-insensitive)', async () => {
    const tag = unique()
    const taken = await add(body(tag))
    const other = await add(body(unique()))
    for (const res of [
      await create({ ...body(unique()), name: taken.name.toUpperCase() }),
      await create({ ...body(unique()), code: taken.code.toUpperCase() }),
      await call('admin', 'put', `/${taken.id}`, { name: other.name }),
    ]) {
      expect(res.status).toBe(409)
      expect(res.body).toMatchObject({
        code: Err.DUPLICATE.code,
        msg: t('zh-CN', Err.DUPLICATE.key),
      })
    }
  })

  it('404: unknown ids for get, update, enabled, delete; a batch with one unknown id deletes nothing', async () => {
    const { id } = await add(body(unique()))
    for (const res of [
      await call('admin', 'get', `/${MISSING}`),
      await call('admin', 'put', `/${MISSING}`, {}),
      await call('admin', 'put', `/${MISSING}/enabled`, { enabled: true }),
      await call('admin', 'delete', `/${MISSING}`),
      await call('admin', 'post', '/batch-delete', { ids: [id, MISSING] }),
    ]) {
      expect(res.status).toBe(404)
      expect(res.body.code).toBe(Err.NOT_FOUND.code)
    }
    await call('admin', 'get', `/${id}`).expect(200)
  })

  it('the same create submitted twice within 3 s → 429 (@Idempotent)', async () => {
    const tag = unique()
    await create(body(tag)).expect(201)
    const again = await create(body(tag)).expect(429)
    expect(again.body.code).toBe(Err.TOO_MANY_REQUESTS.code)
  })
})

/** A binary (xlsx) response body as a Buffer. */
const binary = (r: request.Response, cb: (err: Error | null, body: Buffer) => void) => {
  const chunks: Buffer[] = []
  r.on('data', (c: Buffer) => chunks.push(c))
  r.on('end', () => cb(null, Buffer.concat(chunks)))
}
/** The first sheet of an xlsx body (or none). */
async function sheet(body: unknown) {
  const wb = new ExcelJS.Workbook()
  await wb.xlsx.load(body as Parameters<typeof wb.xlsx.load>[0])
  return wb.worksheets[0]
}
const cells = (ws: ExcelJS.Worksheet, row: number, length: number) =>
  Array.from({ length }, (_, i) => ws.getRow(row).getCell(i + 1).value ?? null)

describe('export', () => {
  /** GET /export as the parsed first sheet, with the response. */
  async function exported(who: keyof typeof tokens, query: object, headers: object = {}) {
    const res = await call(who, 'get', '/export')
      .query(query)
      .set(headers as Record<string, string>)
      .buffer(true)
      .parse(binary)
    return { res, ws: res.status === 200 ? await sheet(res.body) : undefined }
  }
  const row = (ws: ExcelJS.Worksheet, n: number) => cells(ws, n, HEADERS.length)

  it('export: every row (no paging) in list order as .xlsx, headers translated, formulas escaped, times in the zone', async () => {
    const tag = unique()
    await add(body(`${tag}-a`, { enabled: false }))
    const { id } = await add(body(`${tag}-b`, { note: '=1+1' }))
    const { res, ws } = await exported('admin', { sort: '-id', pageSize: 1 })
    expect(res.status).toBe(200)
    expect(res.headers['content-type']).toContain('spreadsheetml.sheet')
    expect(res.headers['content-disposition']).toBe('attachment; filename="roles.xlsx"')
    expect(row(ws!, 1)).toEqual(HEADERS.map((k) => t('zh-CN', k)))
    // all live rows, newest first; `=…` gets a `'` prefix
    expect(ws!.actualRowCount).toBe((await count()) + 1)
    expect(row(ws!, 2)[0]).toBe(`${tag}-b`)
    expect(row(ws!, 3)[0]).toBe(`${tag}-a`)
    expect(row(ws!, 2)[7]).toBe("'=1+1")
    // a dict column as its label
    expect(row(ws!, 3)[5]).toBe(await dictLabel('core.enabled', 'false'))
    // created_at (UTC) in core.default_timezone (Asia/Shanghai, +8h) unless X-Timezone says otherwise
    const [{ at }] = await ds.query('SELECT created_at AS at FROM iam_role WHERE id = ?', [id])
    const local = (d: Date, hours: number) =>
      new Date(d.getTime() + hours * 3600_000).toISOString().slice(0, 19).replace('T', ' ')
    expect(row(ws!, 2)[6]).toBe(local(at, 8))
    const utc = await exported('admin', { sort: '-id' }, { 'X-Timezone': 'UTC' })
    expect(row(utc.ws!, 2)[6]).toBe(local(at, 0))
  })

  it('export: English headers and labels for an en-US request', async () => {
    await add(body(unique()))
    const { ws } = await exported('admin', { sort: '-id' }, { 'Accept-Language': 'en-US' })
    expect(row(ws!, 1)).toEqual(HEADERS.map((k) => t('en-US', k)))
    expect(row(ws!, 2)[5]).toBe(await dictLabel('core.enabled', 'true', 'en-US'))
  })

  it('export: 403 without iam.role.export, 400 for a bad query, action-logged', async () => {
    expect((await exported('reader', {})).res.status).toBe(403)
    expect((await exported('admin', { sort: 'enabled' })).res.status).toBe(400)
    const traceId = `${PREFIX}${process.pid}-export`
    await exported('admin', { name: unique() }, { 'X-Request-Id': traceId })
    expect(await logOf(ds, traceId)).toMatchObject({ domain: 'iam.role', verb: 'export', ok: 1 })
  })
})

it('@ActionLog: every write leaves a row with domain iam.role, its verb and the id', async () => {
  const trace = `${PREFIX}${process.pid}-`
  const created = await create(body(unique())).set('X-Request-Id', `${trace}c`).expect(201)
  const { id } = created.body.data
  await call('admin', 'put', `/${id}`, {}).set('X-Request-Id', `${trace}u`)
  await call('admin', 'put', `/${id}/enabled`, { enabled: false }).set('X-Request-Id', `${trace}e`)
  await call('admin', 'delete', `/${id}`).set('X-Request-Id', `${trace}d`)
  await call('admin', 'post', '/batch-delete', { ids: [MISSING] }).set('X-Request-Id', `${trace}b`)
  const expected: [string, object][] = [
    ['c', { verb: 'create', biz_id: String(id), ok: 1 }],
    ['u', { verb: 'modify', biz_id: String(id), ok: 1 }],
    ['e', { verb: 'modify', biz_id: String(id), ok: 1 }],
    ['d', { verb: 'remove', biz_id: String(id), ok: 1 }],
    ['b', { verb: 'remove', biz_id: null, ok: 0, error_msg: Err.NOT_FOUND.key }],
  ]
  for (const [suffix, row] of expected)
    expect(await logOf(ds, `${trace}${suffix}`)).toMatchObject({
      domain: 'iam.role',
      username: 'admin',
      ...row,
    })
})

it('Swagger documents every route', async () => {
  const doc = (await request(app.getHttpServer()).get('/api/docs-json').expect(200)).body
  expect(
    Object.keys(doc.paths)
      .filter((p) => p.startsWith(URL))
      .sort(),
  ).toEqual([
    URL,
    `${URL}/batch-delete`,
    `${URL}/export`,
    `${URL}/menu-tree`,
    `${URL}/options`,
    `${URL}/{id}`,
    `${URL}/{id}/data-scope`,
    `${URL}/{id}/enabled`,
    `${URL}/{id}/members`,
    `${URL}/{id}/members/revoke`,
    `${URL}/{id}/menus`,
  ])
  expect(
    doc.paths[URL].get.responses['200'].content['application/json'].schema.properties.data,
  ).toMatchObject({ properties: { items: { type: 'array' }, total: { type: 'integer' } } })
})
